'use strict';
const $=id=>document.getElementById(id), C=Tracker, KEY='toggle-task.v1';
let state, editing=null, undo=null, readOnly=false;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):C.seed();if(state.version!==1||!Array.isArray(state.sessions)||!Array.isArray(state.projects)||!Array.isArray(state.users))throw Error('Formato desconocido');}catch(e){state=C.seed();readOnly=true;setTimeout(()=>notify('No se pudieron leer los datos guardados. No se sobrescribirán. '+e.message),0);}
function notify(message,action){const n=$('notice');n.replaceChildren(document.createTextNode(message));if(action){const b=document.createElement('button');b.textContent='Deshacer';b.onclick=action;n.append(b);}n.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.remove('show'),9000);}
function mutate(fn){try{if(readOnly)throw Error('Guardado bloqueado para proteger los datos.');const disk=localStorage.getItem(KEY);if(disk&&JSON.parse(disk).revision!==state.revision)throw Error('Otra ventana ha cambiado los datos. Recarga para continuar.');const next=structuredClone(state);fn(next);next.revision++;localStorage.setItem(KEY,JSON.stringify(next));state=next;render();$('saveState').textContent='Guardado local';return true;}catch(e){$('saveState').textContent='No guardado';notify(e.message);return false;}}
function options(select,items,current){select.replaceChildren(...items.map(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;return o;}));if(items.some(x=>x.id===current))select.value=current;}
function el(tag,text,cls){const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;}
const projectName=id=>state.projects.find(p=>p.id===id)?.name||'Proyecto desconocido';
const userName=id=>state.users.find(p=>p.id===id)?.name||'Perfil desconocido';
function inPeriod(s,period){const now=new Date();const start=period==='today'?new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime():period==='week'?Date.now()-7*86400000:0;return s.end>start;}
function filtered(){const q=$('search').value.toLocaleLowerCase();return state.sessions.filter(s=>($('allUsers').checked||s.userId===state.userId)&&inPeriod(s,$('period').value)&&(s.description+' '+projectName(s.projectId)).toLocaleLowerCase().includes(q)).sort((a,b)=>b.start-a.start);}
function action(text,callback){const b=el('button',text);b.onclick=callback;return b;}
function render(){const current=$('project').value;options($('project'),state.projects.filter(p=>!p.archived),state.active?.projectId||current);options($('user'),state.users,state.userId);$('user').disabled=!!state.active;
for(const id of ['project','description','workType','units'])$(id).disabled=!!state.active;
if(state.active){$('description').value=state.active.description;$('workType').value=state.active.workType;$('units').value=state.active.units;}
$('toggle').textContent=state.active?'■ Parar':'▶ Iniciar';$('toggle').classList.toggle('running',!!state.active);$('miniToggle').textContent=state.active?'Parar':'Iniciar';
$('activeHint').textContent=state.active?'En marcha · se recupera al reabrir':'Todo listo. Empieza cuando quieras.';$('miniDescription').textContent=state.active?.description||'Listo para empezar';
$('palette').value=state.palette||'lilac';$('theme').value=state.theme||'light';document.body.dataset.palette=state.palette||'lilac';document.body.dataset.theme=state.theme||'light';
renderSessions();renderProjects();renderReports();renderDay();tick();}
function tick(){const value=C.format(state.active?(Date.now()-state.active.start)/1000:0);for(const id of ['clock','menuClock','miniClock'])$(id).textContent=value;document.title=state.active?value+' · Toggle Task':'Toggle Task';}
function renderSessions(){const list=filtered();$('sessionCount').textContent=list.length+' sesiones';$('total').textContent=C.format(list.reduce((n,s)=>n+C.seconds(s),0));const target=$('sessions');target.replaceChildren();if(!list.length){target.append(el('p','Todavía no hay sesiones aquí. Inicia el temporizador o añade una sesión manual.','empty'));return;}
for(const s of list){const row=el('article',null,'session'),detail=el('div',null,'details');detail.append(el('strong',s.description||'Sin descripción'),el('p',projectName(s.projectId)+' · '+s.workType+' · '+s.units+' u. · '+userName(s.userId)),el('p',new Date(s.start).toLocaleString('es-ES')+' — '+new Date(s.end).toLocaleTimeString('es-ES')));row.append(detail,el('time',C.format(C.seconds(s))),action('Continuar',()=>{if(mutate(n=>C.start(n,{projectId:s.projectId,description:s.description,workType:s.workType,units:0})))notify('Nueva sesión iniciada. Unidades a cero para evitar duplicarlas.');}),action('Editar',()=>openEditor(s)),action('Eliminar',()=>{if(mutate(n=>{n.sessions=n.sessions.filter(x=>x.id!==s.id);})){undo=s;notify('Sesión eliminada.',()=>{if(undo&&mutate(n=>C.upsert(n,undo))) {undo=null;notify('Sesión recuperada.');}});}}));target.append(row);}}
function renderProjects(){const target=$('projects');target.replaceChildren();for(const p of state.projects){const ss=state.sessions.filter(s=>s.projectId===p.id),card=el('article',null,'projectcard'),header=el('header');header.append(el('h2',p.name),action(p.archived?'Reactivar':'Archivar',()=>mutate(n=>{if(n.active?.projectId===p.id)throw Error('Detén el temporizador antes de archivar.');n.projects.find(x=>x.id===p.id).archived=!p.archived;})));card.append(header,el('p',p.client+' · '+(p.archived?'Archivado':'Activo')));
const metrics=el('div',null,'metrics');for(const [label,value] of [['Tiempo total',C.format(p.historicalMinutes*60+ss.reduce((a,s)=>a+C.seconds(s),0))],['Sesiones',ss.length],['Participantes',new Set(ss.map(s=>s.userId)).size]]){const v=el('div',label);v.append(el('b',value));metrics.append(v);}card.append(metrics,el('p',C.types.map(t=>t+': '+ss.filter(s=>s.workType===t).reduce((n,s)=>n+s.units,0)+' u.').join(' · ')));if(ss.length)card.append(el('p','Primera sesión: '+new Date(Math.min(...ss.map(s=>s.start))).toLocaleDateString('es-ES')+' · Última: '+new Date(Math.max(...ss.map(s=>s.end))).toLocaleDateString('es-ES')));target.append(card);}}
function renderReports(){const ss=state.sessions.filter(s=>inPeriod(s,$('reportPeriod').value)),total=ss.reduce((n,s)=>n+C.seconds(s),0);$('reports').replaceChildren(el('h1',C.format(total)));for(const p of state.projects){const time=ss.filter(s=>s.projectId===p.id).reduce((n,s)=>n+C.seconds(s),0);if(!time)continue;const card=el('article',null,'projectcard'),bar=el('div',null,'bar'),fill=el('span');fill.style.width=(total?time/total*100:0)+'%';bar.append(fill);card.append(el('strong',p.name+' · '+C.format(time)),bar);$('reports').append(card);}if(!total)$('reports').append(el('p','No hay tiempo registrado en este periodo.','empty'));}
function toggle(){mutate(n=>{if(n.active)C.stop(n);else C.start(n,{projectId:$('project').value,description:$('description').value.trim(),workType:$('workType').value,units:Number($('units').value)});});}
$('timerForm').onsubmit=e=>{e.preventDefault();toggle();};$('miniToggle').onclick=toggle;
$('miniButton').onclick=()=>{$('mini').hidden=!$('mini').hidden;$('miniButton').setAttribute('aria-expanded',String(!$('mini').hidden));};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('mini').hidden=true;$('miniButton').setAttribute('aria-expanded','false');}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('editor').open&&!$('projectEditor').open){e.preventDefault();toggle();}});
const headings={timer:'Un momento para enfocarte.',day:'Tu día, hora a hora.',projects:'De la idea al hecho.',reports:'Así has invertido tu tiempo.',settings:'Tu espacio, a tu manera.'};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{for(const v of Object.keys(headings))$(v+'View').hidden=v!==b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-current',x===b?'page':'false');});$('heading').textContent=headings[b.dataset.view];});
$('user').onchange=()=>mutate(n=>{if(n.active)throw Error('Detén la sesión para cambiar de perfil.');n.userId=$('user').value;});for(const id of ['search','period','allUsers'])$(id).addEventListener('input',renderSessions);$('reportPeriod').onchange=renderReports;
function localDate(t){const d=new Date(t);return new Date(t-d.getTimezoneOffset()*60000).toISOString().slice(0,19);}
function openEditor(s){editing=s?.id||null;$('editTitle').textContent=s?'Editar sesión':'Añadir sesión';options($('editProject'),state.projects.filter(p=>!p.archived||p.id===s?.projectId),s?.projectId||$('project').value);$('editDescription').value=s?.description||'';$('editStart').value=localDate(s?.start||Date.now()-1800000);$('editEnd').value=localDate(s?.end||Date.now());$('editType').value=s?.workType||'Visuales';$('editUnits').value=s?.units||0;$('editError').textContent='';$('editor').showModal();}
$('manual').onclick=()=>openEditor();$('cancelEdit').onclick=()=>$('editor').close();$('editForm').onsubmit=e=>{e.preventDefault();const existing=state.sessions.find(s=>s.id===editing);const session={id:editing||C.id(),userId:existing?.userId||state.userId,projectId:$('editProject').value,description:$('editDescription').value.trim(),start:new Date($('editStart').value).getTime(),end:new Date($('editEnd').value).getTime(),workType:$('editType').value,units:Number($('editUnits').value)};try{C.validate(session,state);}catch(error){$('editError').textContent=error.message;return;}if(mutate(n=>C.upsert(n,session))){$('editor').close();notify('Sesión guardada.');}};
$('newProject').onclick=()=>$('projectEditor').showModal();$('cancelProject').onclick=()=>$('projectEditor').close();$('projectForm').onsubmit=e=>{e.preventDefault();if(mutate(n=>{const name=$('projectName').value.trim(),client=$('clientName').value.trim();if(!name||!client)throw Error('Escribe el nombre y el cliente.');if(n.projects.some(p=>p.name.toLowerCase()===name.toLowerCase()&&p.client.toLowerCase()===client.toLowerCase()))throw Error('Ya existe ese proyecto para el cliente.');n.projects.push({id:C.id(),name,client,historicalMinutes:Number($('historical').value),archived:false});})){$('projectEditor').close();$('projectForm').reset();}};
$('profileForm').onsubmit=e=>{e.preventDefault();if(mutate(n=>{if(n.active)throw Error('Detén el temporizador antes de cambiar de perfil.');const name=$('profileName').value.trim();if(!name)throw Error('Escribe un nombre.');if(n.users.some(u=>u.name.toLowerCase()===name.toLowerCase()))throw Error('Ese perfil ya existe.');const id=C.id();n.users.push({id,name});n.userId=id;}))$('profileForm').reset();};
for(const id of ['palette','theme'])$(id).onchange=()=>mutate(n=>{n[id]=$(id).value;});
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('backup').onclick=()=>download('toggle-task-backup.json',JSON.stringify(state,null,2),'application/json');
$('export').onclick=()=>download('toggle-task-sesiones.csv',C.csv([['ID','Proyecto','Actividad','Perfil','Inicio','Fin','Segundos','Tipo','Unidades'],...filtered().map(s=>[s.id,projectName(s.projectId),s.description,userName(s.userId),new Date(s.start).toISOString(),new Date(s.end).toISOString(),C.seconds(s),s.workType,s.units])]),'text/csv;charset=utf-8');
window.addEventListener('storage',e=>{if(e.key===KEY){notify('Los datos han cambiado en otra ventana. Recarga para continuar.');readOnly=true;$('toggle').disabled=true;$('saveState').textContent='Recarga necesaria';}});
if(!localStorage.getItem(KEY)&&!readOnly){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{readOnly=true;notify('El navegador no permite guardar datos.');}}
function dayBounds(){const [y,m,d]=$('dayDate').value.split('-').map(Number);const start=new Date(y,m-1,d),end=new Date(y,m-1,d+1);return [start.getTime(),end.getTime()];}
function renderDay(){if(!$('dayDate').value)return;const [start,end]=dayBounds();const records=state.sessions.filter(s=>s.userId===state.userId&&C.dayOverlap(s,start,end)>0).sort((a,b)=>a.start-b.start);$('dayTotal').textContent=C.format(records.reduce((n,s)=>n+C.dayOverlap(s,start,end)/1000,0));$('daySessions').replaceChildren();for(const s of records){const row=el('article',null,'session');row.append(el('div',new Date(Math.max(s.start,start)).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})+' – '+new Date(Math.min(s.end,end)).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})),el('div',(s.description||'Sin descripción')+' · '+projectName(s.projectId),'details'),el('time',C.format(C.dayOverlap(s,start,end)/1000)),action('Editar',()=>openEditor(s)));$('daySessions').append(row);}
const timeline=$('timeline');timeline.replaceChildren();for(let h=0;h<24;h++){const cell=el('div',String(h).padStart(2,'0')+':00','hour');cell.style.top=(h/24*100)+'%';timeline.append(cell);}for(const s of records){const b=action((s.description||'Sin descripción')+' · '+C.format(C.dayOverlap(s,start,end)/1000),()=>openEditor(s));b.className='timeblock';b.style.top=((Math.max(s.start,start)-start)/(end-start)*100)+'%';b.style.height=Math.max(2,(Math.min(s.end,end)-Math.max(s.start,start))/(end-start)*100)+'%';timeline.append(b);}if(!records)$('daySessions').append(el('p','No hay sesiones para este día y perfil.','empty')); }
function setDay(date){$('dayDate').value=localDate(date.getTime()).slice(0,10);renderDay();}
$('dayDate').onchange=renderDay;$('previousDay').onclick=()=>{const [s]=dayBounds();const d=new Date(s);d.setDate(d.getDate()-1);setDay(d);};$('nextDay').onclick=()=>{const [s]=dayBounds();const d=new Date(s);d.setDate(d.getDate()+1);setDay(d);};$('today').onclick=()=>setDay(new Date());setDay(new Date());
render();setInterval(tick,500);
